 var head='<section class="card" data-schema-card="'+e(d.documentId)+'" style="margin-top:16px"><div class="card-heading"><h2>'+e(t('schemaReviewTitle'))+' \u2014 '+e(d.originalFilename)+'</h2>'+(approved?'<span class="status-pill ready">'+e(t('importDone'))+'</span>':stat('REVIEW_REQUIRED'))+'</div><p class="empty-helper">'+e(t('schemaReviewHelp'))+'</p>';
 var facts='<div class="settings-list">'+row(t('schemaRows'),String(stats.rows!=null?stats.rows:(s.rowCount||0)))+row(t('schemaUnique'),String(stats.valid||0))+row(t('schemaDuplicates'),String(stats.duplicates||0))+row(t('schemaInvalid'),String(stats.invalid||0))+row(t('schemaSource'),provenance==='MUSE'?t('schemaMuse'):(provenance==='MUSE_PLUS_HEURISTIC'?t('schemaMuse')+' + headers':provenance))+'</div>';
 var table='<div class="data-table-wrap"><table><thead><tr><th>'+e(t('sourceColumn'))+'</th><th>'+e(t('targetField'))+'</th></tr></thead><tbody>'+(s.headers||[]).map(function(h){return '<tr><td><code>'+e(h)+'</code></td><td><select data-column="'+e(h)+'"'+(approved?' disabled':'')+'>'+schemaTargetOptions(targetOf[h]||'')+'</select></td></tr>';}).join('')+'</tbody></table></div>';
 var issues=(s.issues||[]).length?'<details><summary>'+e(t('itemsAttention'))+'</summary><ul>'+(s.issues||[]).slice(0,20).map(function(i){return '<li>row '+e(i.row)+': '+e(i.code)+(i.detail?' \u2014 '+e(i.detail):'')+'</li>';}).join('')+'</ul></details>':'';
 var ambiguities=(s.ambiguities||[]).length?'<details><summary>'+e(t('mappingNotes'))+'</summary><ul>'+(s.ambiguities||[]).slice(0,12).map(function(a){return '<li>'+e(a.target||'mapping')+': '+e(a.reason||'')+'</li>';}).join('')+'</ul></details>':'';
 var action=approved?'':'<div class="modal-actions"><button type="button" class="button button-secondary" data-schema-repropose="'+e(d.documentId)+'">'+e(t('reanalyseMapping'))+'</button><button type="button" class="button button-primary" data-schema-approve="'+e(d.documentId)+'">'+e(t('approveMapping'))+'</button></div>';
