async function approveSchemaMapping(docId){var doc=(S.intake.documents||[]).filter(function(x){return x.documentId===docId;})[0];if(!doc||!doc.schema)return;var card=document.querySelector('[data-schema-card="'+docId+'"]');if(!card)return;var columnTargets={};$$('select[data-column]',card).forEach(function(sel){columnTargets[sel.dataset.column]=sel.value||null;});try{await api('/api/intake/schema/approve',{documentId:docId,mappingHash:doc.schema.schemaHash,columnTargets:columnTargets,actor:'user'});toast(t('importDone'),'success');await load();render();}catch(x){toast(x.message,'error');}}
