function documentPage(){var ds=S.intake.documents||[],cs=S.intake.candidates||[];var input='<label class="button button-primary file-picker">＋ '+e(t('chooseFile'))+'<input type="file" data-upload accept=".pdf,.png,.jpg,.jpeg,.csv,.xlsx,.xls,.txt,.json"></label>';var schemaCards=ds.filter(function(d){return d.schema;}).map(schemaCard).join('');var batchButton=cs.some(function(c){return c.status==='READY_TO_CONFIRM';})?'<button type="button" class="button button-primary" data-batch-confirm="1">'+e(t('batchPost'))+'</button>':'';var cards=ds.slice().reverse().map(function(d){var c=(d.candidates&&d.candidates.length?d.candidates:cs).find(function(x){return x.candidateId&&(!x.documentId||x.documentId===d.documentId);});return '<article class="card document-card"><div class="document-top"><div><h3>'+e(d.originalFilename||t('documentsTitle'))+'</h3><p class="document-meta">'+e(date(d.createdAt||d.uploadedAt))+' · '+e(d.detectedMimeType||d.declaredMimeType||'')+'</p></div>'+stat(d.processingStatus)+'</div><div class="step-list"><span class="step-chip done">1. '+e(t('chooseFile'))+'</span><span class="step-chip '+(d.extraction?'done':'')+'">2. '+e(t('processing'))+'</span><span class="step-chip '+((d.candidates||[]).length?'done':'')+'">3. '+e(t('needsReview'))+'</span><span class="step-chip '+(d.processingStatus==='POSTED'?'done':'')+'">4. '+e(t('posted'))+'</span></div>'+((d.warnings||[]).length?'<details><summary>'+e(t('details'))+'</summary><p>'+e(d.warnings.join(' '))+'</p></details>':'')+'<div class="document-actions"><a class="text-link" href="/api/intake/original?documentId='+encodeURIComponent(d.documentId)+'" download>'+e(t('sourceLineage'))+' ↗</a>'+(c?'<button class="button button-secondary" data-evidence="'+e(c.candidateId)+'">'+e(t('openEvidence'))+'</button>':'')+'</div></article>';}).join('');return '<div class="page-heading"><div><span class="eyebrow">'+e(t('business'))+'</span><h1>'+e(t('documents'))+'</h1><p>'+e(t('documentsSub'))+'</p></div>'+input+'</div><div class="alert info"><span>ⓘ</span><span>'+e(t('uploadHint'))+'</span></div>'+(cards?'<div class="document-grid" style="margin-top:15px">'+cards+'</div>':'<section class="card" style="margin-top:15px"><div class="empty-state"><h3>'+e(t('noDocuments'))+'</h3><p>'+e(t('emptyHelp'))+'</p>'+input+'</div></section>')+schemaCards+(cs.length?'<section class="card" style="margin-top:16px"><div class="card-heading"><h2>'+e(t('itemsAttention'))+'</h2>'+batchButton+'</div><div class="data-table-wrap"><table><thead><tr><th>'+e(t('description'))+'</th><th>'+e(t('amount'))+'</th><th>'+e(t('status'))+'</th><th>'+e(t('action'))+'</th></tr></thead><tbody>'+cs.filter(function(c){return !['POSTED','REJECTED'].includes(c.status);}).map(candidateRow).join('')+'</tbody></table></div></section>':'');}
 function candidateRow(c){var f=c.current||{},amount=f.amount?(f.currency||'')+' '+f.amount:'?',ok=['READY_TO_CONFIRM','CONFIRMED'].includes(c.status)||Boolean(c.confirmation);return '<tr><td>'+e(f.description||f.counterparty||t('transaction'))+'</td><td class="num">'+e(amount)+'</td><td>'+stat(c.status)+'</td><td>'+(!['POSTED','REJECTED','CONFIRMED'].includes(c.status)?'<button class="button button-secondary" data-review="'+e(c.candidateId)+'">Review</button>':'')+(ok&&c.status!=='CONFIRMED'?'<button class="button button-secondary" data-confirm="'+e(c.candidateId)+'">'+e(t('confirm'))+'</button>':'')+(!['POSTED','REJECTED','CONFIRMED'].includes(c.status)?'<button class="button button-tertiary" data-reject="'+e(c.candidateId)+'">'+e(t('reject'))+'</button>':'')+'</td></tr>';}
 async function openTaxCorrection(){var d=$('#taxCorrection'),x=S.taxEstimate;if(!d||!x)return;
$('#txYear').value=String(x.taxYear);$('#txResidence').value=x.facts.residence;$('#txIncomeScope').value=x.facts.incomeScope;$('#txExpense').value=x.facts.expenseTreatment;
$('#txMessage').hidden=true;d.dataset.revision=String((x.revisions||[]).length);d.showModal();}
async function saveTaxCorrection(ev){ev.preventDefault();var d=$('#taxCorrection');var changes={taxYear:$('#txYear').value,residence:$('#txResidence').value,incomeScope:$('#txIncomeScope').value,expenseTreatment:$('#txExpense').value};
try{await api('/api/tax/estimate/correct',{changes:changes,actor:'user'});await load();d.close();render();toast(t('correctionSaved'),'success');}catch(x){$('#txMessage').hidden=false;$('#txMessage').textContent=x.message;}}
async function recalculateTaxEstimate(){var box=$('#taxEstimateError');if(box)box.hidden=true;try{await api('/api/tax/estimate/recalculate',{actor:'user'});await load();render();toast(t('recalculated'),'success');}catch(x){if(box){box.hidden=false;box.textContent=x.message;}}}
function provisionalCard(){var x=S.taxEstimate;if(!x)return '';if((S.ws&&S.ws.jurisdiction)!=='JP')return '';var est=x.estimate,cur=x.currency||'JPY',amt=est?money(est.amountMinor,cur):t('notAvailable');
var blockers=(x.blockers||[]).map(function(b){return '<li><code>'+e(b.code)+'</code> '+e(b.detail||'')+'</li>';}).join('');
var assumptions=(x.assumptions||[]).map(function(a){return '<li>'+e(a)+'</li>';}).join('');
var range=x.coverage?(x.coverage.bracketLow+' - '+x.coverage.bracketHigh+' @ '+x.coverage.rate):'&mdash;';
return '<section class="card provisional-card" id="provisionalCard"><div class="card-heading"><h2>'+e(t('estimatedTax'))+' &mdash; <span class="status-pill pending">'+e(t('provisional'))+'</span></h2><span class="status-pill">'+e(t('taxYear'))+' '+e(String(x.taxYear))+'</span></div>'
+'<div class="metric-value tax-metric">'+e(amt)+'</div>'
+'<p class="empty-helper">'+e(x.basisNote||'')+'</p>'
+'<div class="settings-list">'+row(t('ruleStatus'),x.approvalStatus)+row(t('rulesChecked'),range)+row(t('postedJournals'),String(x.figures?x.figures.journalCount:''))+row(t('taxableBase'),money(x.figures?x.figures.taxableBaseMinor:'0',cur))+'</div>'
+(blockers?'<h3>'+e(t('informationStillNeeded'))+'</h3><ul class="plain-list">'+blockers+'</ul>':'')
+(assumptions?'<h3>'+e(t('assumptions'))+'</h3><ul class="plain-list">'+assumptions+'</ul>':'')
+'<div class="modal-actions"><button type="button" class="button button-secondary" id="taxCorrect">'+e(t('correctInformation'))+'</button><button type="button" class="button button-primary" id="taxRecalc">'+e(t('recalculate'))+'</button></div>'
+'<p class="form-note">'+e(t('provisionalNote'))+'</p><p class="form-error" id="taxEstimateError" role="alert" hidden></p></section>';}

function rateText(p){var names=p&&typeof p==='object'?Object.keys(p):[];return names.length?names.slice(0,4).map(function(k){var q=p[k];return k+'='+String(q&&typeof q==='object'?(q.value!=null?q.value:''):q);}).join(' · '):t('notRecorded');}
function estimateCard(){var x=S.taxEstimates||{},items=Array.isArray(x.estimates)?x.estimates:[],unresolved=Array.isArray(x.unresolved)?x.unresolved:[],cur=x.currency||S.ws?.functionalCurrency,provisional=items.some(function(v){return (v.appliedRules||[]).some(function(r){return /DEMO/.test(String(r.governanceStatus||''));});});if(!items.length&&!unresolved.length)return '';var rows=items.map(function(v){var amt=v.taxAmount&&v.taxAmount.amountMinor!=null?money(v.taxAmount.amountMinor,cur):t('notAvailable'),base=v.taxableBase&&v.taxableBase.amountMinor!=null?money(v.taxableBase.amountMinor,cur):t('notRecorded'),rate=v.rate&&v.rate.kind==='FORMULA_DERIVED'?rateText(v.rate.parameters):(typeof v.rate==='string'?v.rate:t('notRecorded')),src=(v.legalSources||[])[0],srcText=src?String(src.legalSourceUrl||src.sourceUrl||src.sourceKind||t('notRecorded')):t('notRecorded'),rule=(v.appliedRules||[])[0],ruleText=rule?String(rule.ruleId||rule.packId||'')+(rule.governanceStatus?' · '+rule.governanceStatus:''):'',disc=(v.demoDisclosures||[])[0],discText=disc?[disc.applicabilityWarning,disc.remainingUncertainty].filter(Boolean).join(' · '):'';return '<div class="activity-item"><strong>'+e(String(v.taxType))+' &middot; '+e(amt)+'</strong><small>'+e(t('amount'))+': '+e(base)+' &middot; '+e(t('taxEstimate'))+': '+e(rate)+'</small>'+(ruleText?'<small>'+e(t('appliedRule'))+': '+e(ruleText)+'</small>':'')+'<small>'+e(t('governmentSource'))+': '+e(srcText)+'</small>'+(discText?'<small>'+e(discText)+'</small>':'')+'</div>';}).join(''),gaps=unresolved.slice(0,8).map(function(v){return '<div class="checklist-row"><span class="check-icon">!</span><div><strong>'+e(String(v.taxType||v.code))+'</strong><p>'+e(String(v.code))+'</p></div></div>';}).join('');return '<section class="content-grid equal" style="margin-top:15px"><article class="card"><div class="card-heading"><h2>'+e(t('taxEstimate'))+'</h2>'+stat(provisional?'DEMO · PROVISIONAL':(items.length?'CALCULATED':'REVIEW_REQUIRED'))+'</div>'+(rows?'<div class="activity-feed">'+rows+'</div>':'<div class="empty-state"><h3>'+e(t('noTaxAmount'))+'</h3></div>')+'<p class="empty-helper">'+e(t('fromRecords'))+'</p></article><article class="card"><div class="card-heading"><h2>'+e(t('requiredFacts'))+'</h2></div>'+(gaps||'<div class="empty-state"><h3>'+e(t('ready'))+'</h3></div>')+'<p class="empty-helper">'+e(t('taxConditional'))+'</p></article></section>';}
