+'<article class="card"><div class="card-heading"><h2>'+e(t('ruleCoverage'))+'</h2></div>'+(packs.length?'<div class="activity-feed">'+packs.map(function(p){return '<div class="activity-item"><strong>'+e(p.packId||p.id||t('governmentSource'))+'</strong><small>'+e(p.kind||'')+' &middot; '+e(p.governance||t('needsReview'))+' &middot; '+e(p.version||'')+'</small></div>';}).join('')+'</div>':'<div class="empty-state"><h3>'+e(t('noTaxAmount'))+'</h3></div>')
