 var facts='<section class="card"><div class="card-heading"><h2>'+e(t('whatIHeard'))+'</h2></div><div class="settings-list">'+row(t('businessName'),name)+row(t('businessType'),sv('org.businessType'))+row(t('activities'),sv('org.activities'))+row(t('activityRole'),sv('employment.relationship'))+row(t('bookCurrency'),cur)+row(t('workLocation'),work)+row(t('nationality'),sv('user.nationality'))+row(t('fullName'),sv('user.displayName'))+'</div>'+(missing.length?'<p class="empty-helper">'+e(t('missingInformation'))+': '+e(missing.join(', '))+'</p>':'')+(act?'<p class="empty-helper">'+e(t('workspaceActiveHelp'))+'</p>':'')+'</section>';
