 function chatBubble(m){var a=m.role==='assistant',out='';if(a){if(m.result?.status==='MUSE_UNAVAILABLE')out+='<div class="assistant-result">'+e(t('assistantFallback'))+'</div>';var parts=(m.result?.sections||[]).reduce(function(acc,x){var lines=[];if(x?.display)lines.push(x.display);if(Array.isArray(x?.facts))x.facts.forEach(function(f){if(f?.display)lines.push(f.display);});if(x?.explanation)lines.push(typeof x.explanation==='string'?x.explanation:(x.explanation.text||''));return acc.concat(lines.filter(Boolean));},[]);out+=parts.length?parts.map(function(x){return '<p>'+e(x)+'</p>';}).join(''):'<p>'+e(t('noGuidance'))+'</p>';}else out=e(m.text);return '<div class="chat-message '+(a?'':'user')+'"><span class="chat-avatar">'+(a?'B':e(name()[0]||'U'))+'</span><div class="chat-bubble '+(m.error?'error':'')+'">'+out+(m.error?'<details><summary>'+e(t('errorDetails'))+'</summary><pre>'+e(m.error)+'</pre></details>':'')+'</div></div>';}
